const CHEFES = {"word": {"nome": "Barão Bagunça (versão Word)", "cor": "#3a0ca3", "olho": "#ff006e", "selo": "docs", "regras": [["Documento", "Proposta técnica da Horizonte: 11 seções, 6 páginas"], ["Como lutar", "A turma resolve no quadro. Depois cada um marca aqui."]], "fim": "O Barão Bagunça fugiu do Word! A proposta tem capa, sumário, cabeçalho e PDF. Mas ele correu para a planilha...", "etapas": [{"q": "O sumário saiu vazio, a página 4 precisa ficar em Paisagem e o número de página sumiu. Qual sequência resolve TUDO?", "o": ["Aplicar Título 1/2 e atualizar o sumário; quebras de seção na página 4 em Paisagem; Inserir > Número de Página", "Digitar o sumário à mão; virar o documento todo em Paisagem; numerar à mão", "Exportar para PDF e corrigir no PDF", "Apertar Enter até ajeitar"], "c": 0, "e": "Estilos alimentam o sumário, seção permite orientação diferente e o número de página é automático.", "w": ["Tudo à mão quebra na próxima mudança, e Paisagem no documento todo deita todas as páginas.", "PDF não é feito para editar.", "Enter não cria sumário, nem seção, nem número."]}, {"tipo": "chips", "q": "Quais destes ficam automaticamente em TODAS as páginas? Marque todos.", "ops": ["Cabeçalho", "Rodapé com número de página", "Folha de Rosto", "Nota de rodapé"], "certo": ["Cabeçalho", "Rodapé com número de página"], "e": "Folha de rosto é só a capa; a nota de rodapé aparece só na página do termo."}, {"q": "O texto colado do site do fabricante está todo sublinhado de vermelho, mas em português correto. O que fazer?", "o": ["Selecionar e definir o idioma de revisão como Português (Brasil)", "Adicionar cada palavra ao dicionário", "Desligar a revisão", "Trocar a fonte"], "c": 0, "e": "O trecho veio marcado com outro idioma.", "w": ["Funcionaria, mas você estaria ensinando ao Word palavras que ele já conhece.", "Os erros reais também deixariam de aparecer.", "Fonte não muda idioma."]}, {"q": "A pesquisa da equipe cita \"Fonte: internet\". O que a comissão vai dizer?", "o": ["Que falta a fonte de verdade: título, quem publicou, link completo e data de acesso", "Que está ótimo", "Que basta escrever Google", "Que fonte não importa"], "c": 0, "e": "\"Internet\" não permite conferir nada.", "w": ["Não dá para conferir a informação.", "Google é o buscador, não a fonte.", "Informação sem fonte perde credibilidade."]}, {"q": "A equipe dividiu tarefas, cumpriu o prazo e todos revisaram o texto. Que tipo de competência a comissão vai elogiar?", "o": ["Soft skills (colaboração, organização e gestão do tempo)", "Hard skills de Excel", "Nenhuma", "Só a formatação"], "c": 0, "e": "Organização e trabalho em equipe são soft skills.", "w": ["Excel não entrou nesse trabalho de equipe.", "Essas atitudes contam muito no trabalho.", "A formatação é hard skill; o elogio aqui é ao comportamento."]}]}, "planilha": {"nome": "Dragão do #DIV/0!", "cor": "#d62828", "olho": "#ffd166", "selo": "planilha", "regras": [["Guias", "01_PESQUISA • 02_PROPOSTA • 03_DISTRIBUICAO • 04_EVOLUCAO • 05_RESUMO"], ["Como lutar", "A turma resolve no quadro. Depois cada um marca aqui."]], "fim": "O Dragão do #DIV/0! caiu! A proposta comercial calcula, decide e mostra os gráficos. Agora o Barão foi para o Outlook...", "etapas": [{"q": "Notebook: 48 unidades a R$ 4.200,00, com 5% de desconto. Qual fórmula dá o TOTAL do item (Qtd em C2, Valor em D2, Desconto em E2)?", "o": ["=C2*D2*(1-E2)", "=C2*D2-E2", "=C2+D2*(1-E2)", "=C2*D2*E2"], "c": 0, "e": "Total = quantidade × valor unitário × (1 − desconto) = R$ 191.520,00.", "w": ["Tira 0,05 real, não 5%.", "Soma a quantidade com o preço.", "Isso dá só o valor do desconto."]}, {"q": "O investimento passou de R$ 315.000 (2025, em B5) para R$ 412.380 (2026, em B6). Qual fórmula mostra a evolução em %?", "o": ["=(B6-B5)/B5", "=B6/B5", "=B6-B5", "=(B5-B6)/B6"], "c": 0, "e": "Variação = (novo − antigo) ÷ antigo ≈ 30,9%.", "w": ["Dá 1,309: precisaria subtrair 1.", "Dá a diferença em reais, não em %.", "Inverteu o antigo e o novo."]}, {"tipo": "chips", "q": "Quais fórmulas estão CORRETAS no Excel em português? Marque todas.", "ops": ["=SOMA(F2:F8)", "=MÉDIA(D2:D8)", "=SE(F9>500000;\"Acima\";\"OK\")", "=MEDIA(D2:D8)", "=SOMA(F2,F8)"], "certo": ["=SOMA(F2:F8)", "=MÉDIA(D2:D8)", "=SE(F9>500000;\"Acima\";\"OK\")"], "e": "MEDIA sem acento dá #NOME?; a vírgula não separa argumentos no Excel em português."}, {"q": "O PROCV que busca o preço do Access Point dá #N/D, mas o item existe na guia 01_PESQUISA. Causa mais provável:", "o": ["O texto procurado está diferente (um espaço a mais ou um nome escrito de outro jeito)", "Faltou negrito", "A coluna está estreita", "O gráfico está errado"], "c": 0, "e": "#N/D = não encontrou um valor IDÊNTICO na primeira coluna.", "w": ["Negrito não muda a busca.", "Coluna estreita mostra #####.", "O gráfico não interfere no PROCV."]}, {"q": "Qual dupla de gráficos o Edital pede na guia de evolução e no resumo?", "o": ["Linha para a evolução 2022–2026 e pizza (ou colunas) para a composição do valor", "Duas pizzas da evolução", "Só uma tabela", "Radar para tudo"], "c": 0, "e": "Linha mostra o tempo; pizza ou colunas mostram a composição.", "w": ["Pizza não mostra evolução no tempo.", "O Edital pede pelo menos dois gráficos.", "Radar é difícil de ler para esses dados."]}]}, "comissao": {"nome": "Barão Bagunça, o Falso Comissário", "cor": "#14112a", "olho": "#ff006e", "selo": "edital", "regras": [["Proposta", "Excel, Word (PDF), PowerPoint e e-mail de protocolo"], ["Como lutar", "A turma resolve no quadro. Depois cada um marca aqui."]], "fim": "O Barão Bagunça foi desmascarado! A Horizonte entregou uma proposta coerente e defendeu cada escolha. A turma dominou o Pacote Office!", "etapas": [{"q": "O total no Excel é R$ 412.380,00; no PowerPoint está R$ 410.000,00. O que acontece pelas regras do Edital?", "o": ["Perde pontos: o valor do Word e do PowerPoint deve ser igual ao do Excel", "Nada, arredondar é normal", "Ganha pontos por ser mais barato", "A comissão nem olha"], "c": 0, "e": "Coerência entre os arquivos é regra do item 14.", "w": ["Arredondar cria divergência.", "O valor real é o do Excel.", "A comissão confere e faz perguntas."]}, {"tipo": "chips", "q": "Quais anexos vão no e-mail de protocolo? Marque todos.", "ops": ["Proposta técnica e comercial em PDF", "Planilha Excel completa", "Apresentação PowerPoint", "As fotos da equipe", "O .docx editável no lugar do PDF"], "certo": ["Proposta técnica e comercial em PDF", "Planilha Excel completa", "Apresentação PowerPoint"], "e": "Os três do item 10.2."}, {"q": "O e-mail de protocolo vai para a comissão. O coordenador do curso precisa acompanhar. Onde colocar o coordenador?", "o": ["Cc", "Para", "Cco", "Assunto"], "c": 0, "e": "Cc é para quem precisa saber; Para é para quem vai agir.", "w": ["Ele não é quem recebe a proposta.", "Ninguém saberia que ele recebeu.", "Assunto não é destinatário."]}, {"q": "Um integrante quer colar a planilha com os dados da equipe numa IA pública para \"melhorar o texto\". O conselho certo:", "o": ["Tirar dados pessoais e sigilosos antes; e revisar tudo o que a IA devolver", "Colar tudo, a IA é segura", "Nunca usar IA para nada", "Pedir à IA para inventar os preços"], "c": 0, "e": "IA com critério: sem dados sensíveis e com revisão humana.", "w": ["O que você cola pode ser guardado pelo serviço.", "IA bem usada ajuda; o problema é o mau uso.", "Preço inventado é informação falsa: reduz a pontuação."]}, {"q": "Na defesa, a comissão pergunta: \"Por que vocês não escolheram o notebook mais barato?\". A melhor resposta mostra:", "o": ["Os critérios: atende a especificação mínima, tem garantia e suporte melhores e bom custo-benefício, com a fonte da pesquisa", "Que gostamos da cor", "Que a IA escolheu", "Que não deu tempo de pesquisar"], "c": 0, "e": "Decisão justificada com dados e fontes é o que o Edital chama de defesa.", "w": ["Gosto pessoal não justifica gasto público.", "A decisão e a responsabilidade são da equipe.", "Mostra falta de planejamento."]}]}};
